const remoteRepositoryExists = `-- name: RemoteRepositoryExists :one
SELECT EXISTS (SELECT 1 FROM repositories WHERE id = $1::bigint)::bool
`

// Whether a repository row exists, for the replay of a discard.
func (q *Queries) RemoteRepositoryExists(ctx context.Context, repoID int64) (bool, error) {
	row := q.db.QueryRow(ctx, remoteRepositoryExists, repoID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

const remoteStoredVersionFiles = `-- name: RemoteStoredVersionFiles :many
SELECT pv.version, i.path
  FROM packages p
  JOIN package_versions pv ON pv.package_id = p.id AND pv.trashed_at IS NULL
  JOIN items i ON (i.version_id = pv.id OR i.id = pv.lead_item_id) AND i.trashed_at IS NULL AND i.kind = 'file'
 WHERE p.repo_id = $1::bigint AND p.name = $2::text
 ORDER BY pv.version, i.path
 LIMIT 10000
`

type RemoteStoredVersionFilesParams struct {
	RepoID int64
	Name   string
}

type RemoteStoredVersionFilesRow struct {
	Version string
	Path    string
}

// The stored files of a package's versions in a repository by the generic package rows: the items linked to a live version and the
